		if !gitRedirectingEnv[name] {
			env = append(env, kv)
		}
	}
	cmd.Env = append(env, "GIT_NO_REPLACE_OBJECTS=1", "GIT_GRAFT_FILE="+os.DevNull)
	return cmd
}

